assert len(samp) == 1
S = json.loads(samp[0][0])
n_trials = samp[0][1]
nj = V13['noop_json']
assert nj['a'] == 0 and nj['b'] == 0 and nj['c'] == nj['_n']
assert all(r['diff'] == 0.0 and not r['pass'] for r in V13['rows'])
assert V15['distinct_prefixes'] == 1 and V15['distinct_selected'] == 1
assert list(V['V14']['first_tokens'].values()) == [V['V14']['n_json_direct_all']]
assert V16['vhat_max_abs_z_style'] == 0.0
assert V['V17']['hits'] == [['$.calibration.s4_control', '効いた']]
syn = V['V5']['synthetic']
r13 = '・'.join('%s の %s（JSON 直答の中で %d/%d → %d/%d）' % (r['row'].split('|', 1)[1], r['letter'], r['k0'], r['n0'], r['k1'], r['n1']) for r in V13['rows'] if r['letter'] == 'c')
fr13 = '・'.join('%s の %s（z %.2f）' % (r[0].split('|', 1)[1], r[1], r[2]) for r in V13['facts_rows'] if r[3])
nc = V['V21']

K = ['| 番号 | 誰の主張 | 主張 | 確かめ方 | 結果 |', '|---|---|---|---|---|']
def k(no, who, claim, how, res):
    K.append('| K%d | %s | %s | %s | %s |' % tuple([no] + [x.replace('|', '｜') for x in (who, claim, how, res)]))   # セルの中の縦棒は全角にする（表が崩れないように）

